  'data.brood-chamber': 'Komora lęgowa',
  'swarm.brood.desc': 'Żywy organ lęgowy Matki Roju. Co 3 godziny gry wytwarza jednego Desantowca kosztem 20 biomasy, 8 metalu i 2 mikroelektroniki na jednostkę transportową. Wzrost ustaje w walce, przy braku surowców lub przy zapełnionej ładowni desantowej.',
  'data.swarm-leviathan': 'Lewiatan',
  'data.leviathan': 'Lewiatan',
  'data.leviathan-brood': 'Lęg Lewiatana',
  'swarm.leviathan-brood.desc': 'Żywe łono lęgowe Lewiatana. Co 3 godziny gry hoduje 6 Desantowców: po 20 biomasy, 8 metalu i 2 mikroelektroniki za każdego. Wzrost ustaje w walce, przy braku surowców lub przy zapełnionej ładowni desantowej.',
  'data.hive-call': 'Zew Ula',
  'data.devour-world': 'Pożarcie świata',
  'data.swarm-instinct': 'Instynkt Roju',
  'swarm.intel.economy': 'Rój pochłania materię organiczną do budowy tkanek, metal do szkieletów i pancerzy oraz mikroelektronikę do hodowli przewodzących węzłów neuronowych. Światy przemysłowe napędzają jego ekspansję: sama biomasa to za mało.',
  'swarm.intel.brood': 'Matka Roju nosi komorę lęgową — organ hodujący naziemnych Desantowców. Zużywa biomasę, metal i mikroelektronikę; stworzenia zajmują przestrzeń desantową i zdobywają powierzchnię w standardowym szturmie. Sama obecność Matki nie infekuje świata.',
  'swarm.intel.updated': 'Nowe dane',
  'swarm.intel.tab': 'Akta',
  'swarm.intel.title': 'Akta Roju',
  'swarm.intel.lore': 'Obserwując Rój przy każdym kontakcie, poznajemy jego skład i zachodzące zmiany. Uwzględniono tu wyłącznie zaobserwowane formacje, a nie całą armię Roju.',
  'swarm.intel.empty': 'Brak zidentyfikowanych formacji. Sam impuls na radarze nie ujawnia składu floty.',
