  'pve.pirates.title': 'Pierwsza bitwa · Piraci',
  'pve.pirates.approach': 'W pobliżu znajduje się baza piratów z dwoma fregatami. Wybierz flotę początkową, kliknij „Kurs” i wskaż bazę. Twoje siły wystarczą do zwycięstwa w tej potyczce. Jest to cel opcjonalny: fale Roju nadciągają bez przerwy.',
  'pve.pirates.travel': 'Flota zmierza do bazy. Po napotkaniu piratów walka rozpocznie się samoczynnie. Poczekaj na dotarcie na miejsce; kontrola prędkości czasu znajduje się u dołu ekranu.',
  'pve.pirates.battle': 'Bitwa się rozpoczęła. Otwórz jej okno: znajdziesz tam skład stron, wytrzymałość i odliczanie do kolejnej rundy. Obrażenia rozliczane są w rundach. Rozkaz odwrotu wydaje się w karcie floty.',
  'pve.pirates.occupy': 'Flota piratów została rozbita, lecz baza wciąż należy do nich. Twoja flota początkowa posiada oddział desantowy: przemieść okręty na niską orbitę i wydaj rozkaz „Szturm”, aby przejąć opuszczoną bazę.',
  'pve.pirates.won': 'Baza zdobyta, pierwsza walka dobiegła końca. Sprawdź poniesione straty i przygotuj obronę przed Rojem. Zwycięstwo w wyprawie jest jeszcze przed tobą.',
  'pve.pirates.cleared': 'Cel piracki został już zlikwidowany. Kontynuuj przygotowania do odparcia fal Roju.',
  'pve.pirates.recover': 'Nie posiadasz obecnie floty bojowej. Odbuduj siły w stoczni macierzystej lub odłóż piratów na później. Wyprawa trwa.',
  'pve.pirates.show': 'Pokaż bazę',
  'pve.pirates.open-battle': 'Otwórz bitwę',
  'run.abandon.lost.title': 'Flota utracona',
  'run.abandon.lost.text': 'Nie pozostał żaden okręt. Odbuduj flotę w stoczni lub zakończ wyprawę: otrzymasz nagrody za fale, zadania i zniszczonych wrogów jak za porażkę.',
  'run.abandon.ask.title': 'Zakończyć wyprawę?',
  'run.abandon.ask.text': 'Wyprawa zakończy się natychmiastową porażką. Nagrody: za przetrwane fale, zadania i wyeliminowanych przeciwników.',
  'run.abandon.rebuild': 'Odbuduj flotę',
  'run.abandon.back': 'Kontynuuj',
  'run.abandon.go': 'Zakończ wyprawę',
  'run.exit.title': 'Opuścić wyprawę?',
  'run.exit.text': 'Do menu — wyprawa zostanie zapisana i będziesz mógł ją wznowić w tym samym miejscu. Zakończenie — porażka; nagrody za fale, zadania i zniszczonych wrogów.',
  'run.exit.double': 'Na ekranie wyników nagrodę można podwoić za obejrzenie reklamy.',
