  'codex.tag.ship': 'Okręt',
  'codex.term.async.body': 'Świat toczy się w czasie rzeczywistym 24/7 — nawet gdy wyjdziesz z gry. Rozkazy zajmują całe godziny: wyznacz kurs, wyłącz grę i wróć po wynik.',
  'codex.term.async.title': 'Świat asynchroniczny',
  'codex.term.attack.body': 'Siła salwy, gdy ta flota atakuje. Gdy jest atakowana, odpowiada [[defense|obroną]]. W salwie strzela tylko [[fire-line|linia ognia]].',
  'codex.term.attack.title': 'Atak',
  'codex.term.capture.body': 'Podbój świata jest dwuetapowy. Najpierw wejdź na orbitę i przełam obronę w kosmosie; jeśli świat ma garnizon — wysadź desant (dywizję naziemną z ładowni).',
  'codex.term.capture.title': 'Orbita i desant',
  'codex.term.coalition.body': 'Dyplomacja pozwala zawierać pakty i sojusze, lecz koalicja ma limit łącznej siły — nie da się zmówić przeciw jednemu graczowi. Limit chroni równowagę i powstrzymuje efekt kuli śnieżnej.',
  'codex.term.coalition.title': 'Limit koalicyjny',
  'codex.term.defense.body': 'Siła salwy odwetowej, gdy flota zostaje zaatakowana. Obrona nie zmniejsza obrażeń: przyjmują je [[shield|tarcza]] i [[hull|kadłub]].',
  'codex.term.defense.title': 'Obrona',
  'codex.term.fire-line.body': 'W salwie strzela co najwyżej {n} najsilniejszych {n|jednostka|jednostki|jednostek}. Pozostałe tylko przyjmują obrażenia.',
  'codex.term.fire-line.title': 'Linia ognia',
  'codex.term.fog.body': 'Widzisz tylko to, co znajduje się blisko twoich sił i radarów; resztę kryje mgła lub pamięć (ostatni stan). Zwiadowcy i radary poszerzają pole widzenia.',
  'codex.term.fog.title': 'Mgła wojny',
  'codex.term.hull.body': 'Bieżąca i maksymalna wytrzymałość floty. Naprawia się przy własnym świecie ze stocznią lub natychmiast za kredyty.',
  'codex.term.hull.title': 'Kadłub',
  'codex.term.lanes.body': 'Floty nie latają w linii prostej, lecz po szlakach gwiezdnych między światami — trasa układa się automatycznie. Węzły na szlakach można przechwytywać: napotkany wróg oznacza bitwę.',
  'codex.term.lanes.title': 'Szlaki gwiezdne',
  'codex.term.score.body': 'Punkty gromadzą się za posiadłości: świat — 50, inny sektor — 10, budynki dodają zależnie od poziomu. Bitwa o planetę gracza: zwycięstwo +40, porażka −5% punktów. Osiągnij próg, by wygrać.',
  'codex.term.score.title': 'Punkty zwycięstwa',
  'codex.term.shield.body': 'Przyjmuje obrażenia przed [[hull|kadłubem]] i odnawia się bezpłatnie poza walką.',
  'codex.term.shield.title': 'Tarcza',
  'codex.term.speed.body': 'Flota porusza się z prędkością najwolniejszego okrętu. Okręt z [[hull|kadłubem]] poniżej 30% porusza się wolniej.',
  'codex.term.speed.title': 'Prędkość',
  'codex.term.upkeep.body': 'Floty i budynki wymagają codziennego żołdu. Przychód z wydobycia minus utrzymanie = bilans netto; gdy zejdziesz na minus, skarbiec opustoszeje.',
  'codex.term.upkeep.title': 'Utrzymanie',
