  'dossier.building.radar': 'Zasięg {r}. Poziom {lv}: {s}. Sygnały okrętów w promieniu 40 jedn. od punktu zbornego grupy sumują się: średnia sygnatura od 5, silna od 13. Identyfikacja z bliska ujawnia skład.',
