  'dossier.tab.ships.name': 'Flota',
  'dossier.tab.shuttle.desc': 'Eskadra kosmodromu: maszyny (△) stacjonują w hangarze świata i nie pojawiają się na mapie. Przycisk uderzenia wysyła wylot bojowy; cel wybiera się dotknięciem na mapie. Okręt z ładownią zabiera eskadrę ze sobą — ładownia jest widoczna w panelu floty.',
