  'dossier.unit.cruiser.desc': 'Okręt liniowy: {a} ataku, {hp} kadłuba, ładownia na {c} {c|miejsce|miejsca|miejsc} na desant i promy.',
  'dossier.unit.cruiser.name': 'Krążownik',
  'dossier.unit.heavy-cruiser.desc': 'Ciężki okręt liniowy: {a} ataku, {d} obrony, {hp} kadłuba, prędkość {sp}, ładownia na {c} {c|miejsce|miejsca|miejsc}. {n} uniwersalnych przedziałów na dowolne moduły.',
  'dossier.unit.heavy-cruiser.name': 'Wzmocniony krążownik',
  'dossier.unit.default': 'Jednostka bojowa.',
  'dossier.unit.bomber.desc': 'Prom uderzeniowy przeciw okrętom: {a} obrażeń okrętowi, {s} na godzinę budynkom, {hp} kadłuba, zasięg {r}. Atakuje i powraca, nie bierze udziału w bitwie. Miejsce w ładowni: {cs}.',
  'dossier.unit.bomber.name': 'Uderzeniowy strajker',
  'dossier.unit.heavy-striker.desc': 'Ciężki prom przeciw okrętom: {a} obrażeń okrętowi, {s}/godz. budynkom, {hp} kadłuba, zasięg {r} do sąsiedniej prowincji. Ładownia: {cs}. Odblokowany przez Wektory uderzeniowe.',
  'dossier.unit.heavy-striker.name': 'Ciężki strajker uderzeniowy',
  'dossier.unit.interceptor.desc': 'Łowca promów: {s} obrażeń w nie, {a} w okręty. Prędkość {sp}, {hp} kadłuba, zasięg {r}. Startuje sam na atak wroga w pobliżu bazy, zużywając jej paliwo. Ładownia: {cs}.',
  'dossier.unit.interceptor.name': 'Myśliwiec przechwytujący',
  'dossier.unit.frigate.desc': 'Okręt wsparcia: {a} ataku, {d} obrony, {hp} kadłuba. Najwięcej przedziałów na moduły spośród wszystkich kadłubów: {n}. Zajmuje pozycję w drugiej linii.',
  'dossier.unit.frigate.name': 'Fregata',
  'dossier.unit.hero.desc': 'Okręt flagowy dowódcy: {a} ataku, {hp} kadłuba, {b} do ataku i obrony pobliskich okrętów. Po zniszczeniu odbudowywany na świecie macierzystym.',
  'dossier.unit.hero.name': 'Okręt flagowy',
  'dossier.unit.picket-frigate.desc': 'Zwiad floty: antena {r}, moduł radaru +{m} pasuje wyłącznie do tego kadłuba. {a} ataku, {d} obrony, {hp} kadłuba, przedziałów: {n}.',
  'dossier.unit.picket-frigate.name': 'Fregata dozorowa',
  'dossier.unit.scout.desc': 'Prędkość {sp}, sygnatura {sig}, kompaktowy radar +{m}. Nie przejmuje światów.',
  'dossier.unit.scout.name': 'Zwiadowca',
  'dossier.unit.shuttle-carrier.desc': 'Lotniskowiec: ładownia na {bay} {bay|miejsce|miejsca|miejsc} na promy i desant, {a} ataku, {d} obrony, {hp} kadłuba. Promy operują w ruchu. Utrata kadłuba to strata wszystkiego.',
  'dossier.unit.shuttle-carrier.name': 'Lotniskowiec',
