  'data.evac-transport': 'transport z uchodźcami',
  'hero.passive.hull-cutters.desc': 'Kolejne +2% do udziału w łupach, łącznie 5%.',
  'hero.passive.master-batteries.desc': 'Kolejne +3% do obrażeń, łącznie 10%.',
  'hero.passive.master-scavenger.desc': 'Kolejne +5% do udziału w łupach, łącznie 10%.',
  'hero.passive.reclaimed-barrels.desc': 'Kolejne +2% do obrażeń, łącznie 7%.',
  'hero.passive.scavenged-guns.desc': '+5% do obrażeń okrętu dowodzonego przez bohatera.',
  'hero.passive.swarm-instinct.desc': 'Floty Roju w promieniu 42 od Lewiatana poruszają się o 10% szybciej.',
  'hero.passive.wreck-optics.desc': '+3% do udziału w łupach w bitwach z udziałem tego bohatera.',
  'data.field-lab': 'Laboratorium polowe',
  'data.ballistic-model': 'Model balistyczny',
  'hero.passive.ballistic-model.desc': 'W gnieździe: +10% do obrażeń floty bohatera.',
  'hero.passive.field-lab.desc': '+10% do udziału w łupach w bitwach z udziałem tego bohatera.',
  'hero.tree.field-foundry.desc': 'Złom przetapiany jest wprost w ładowni i zasila działa: kolejne +2% do obrażeń okrętu bohatera.',
  'hero.tree.hull-shears.desc': 'Nożyce siłowe rozcinają pancerz, nim zdąży ostygnąć: kolejne +2% do udziału w łupach.',
  'hero.tree.salvage-rig.desc': 'Uchwyty i palniki na wysięgnikach: +3% do udziału w łupach w bitwach bohatera.',
  'hero.tree.scavenged-battery.desc': 'Działa z odzysku: +5% do obrażeń okrętu bohatera.',
  'hero.tree.scavenger-mastery.desc': 'Szczyt rzemiosła: kolejne +5% do udziału w łupach i +3% do obrażeń.',
  'hero.person.commander.name': 'Mark Weir',
  'hero.person.commander.bio': 'Weteran dalekich wypraw. W okrążeniu wyprowadził rozproszone okręty serią pozorowanych manewrów i ocalił załogi. Interfejs neuronalny pomaga mu ogarnąć całość bitwy, lecz decyzji o ludzkim życiu nigdy nie powierza automatyce. Powściągliwy, wymagający, zawsze zostawia odwód do odwrotu.',
  'hero.person.ravager.name': 'Lyra Sain',
  'hero.person.ravager.bio': 'Przeżyła zagładę stacji badawczej, gdzie po raz pierwszy objawił się jej dar psioniczny. Po katastrofie badała granice własnego oddziaływania na przestrzeń. Mówi niewiele, działa zdecydowanie i najsurowiej kontroluje samą siebie. Moc uważa za usprawiedliwioną tylko wtedy, gdy kończy bitwę, a nie ją przedłuża.',
  'hero.person.vanguard.name': 'Darian Cross',
  'hero.person.vanguard.bio': 'Zaczynał jako dowódca eskorty na niebezpiecznych szlakach handlowych. Po ciężkich ranach powrócił na mostek z implantami łączności i analizy taktycznej. Przywykł osobiście sprawdzać nieznany szlak i prowadzić posiłki. Bezpośredni, podejmuje szybkie decyzje i ceni inicjatywę załogi.',
  'hero.person.warden.name': 'Elena Mor',
  'hero.person.warden.bio': 'Przez lata osłaniała konwoje ewakuacyjne na obrzeżach zasiedlonego kosmosu. Dyscyplinę psioniczną rozwijała dla obrony ludzi, nie wyższości nad nimi. Opanowana pod ostrzałem, zna cenę każdego rozkazu. Jej okręt odlatuje ostatni, gdy inni są już bezpieczni.',
  'hero.person.scientist.bio': 'Autor programu, z którego narodził się Rój. Ewakuowano go z kompleksu w pierwszych godzinach kwarantanny — rannego, lecz zdolnego do pracy. Dowództwo nie ufa mu bezgranicznie, lecz zleciło powstrzymanie Roju: zasady systemu zna tylko on. Dla niego to dług wobec tych, których nie zdołał ocalić.',
  'hero.person.main.bio': 'Dowodzisz tym okrętem flagowym. Jego znak rozpoznawczy odpowiada twojemu mianu w grze. Twoją historię tworzą podjęte decyzje: kogo obronić, gdzie zaryzykować i kiedy się wycofać. Zdolności, umiejętności i wyposażenie okrętu przedstawiono na tej karcie.',
  'hero.person.dossier': 'Akta osobowe',
  'hero.person.archetype': 'Specjalizacja',
  'hero.person.grade': 'Rzadkość',
  'hero.person.ships': 'Okrętów we flocie',
  'hero.person.reserve': 'Okręt flagowy w rezerwie',
  'hero.person.ship-stats': 'Parametry okrętu flagowego z modułami',
  'hero.ability.annihilate.desc': 'Zamienia planetę w zasięgu do 500 w martwy świat.',
  'hero.ability.annihilate.name': 'Anihilacja',
  'hero.ability.boarding-translocation.desc': 'Pasywna. Bohater pojawia się jako osobna flota obok dowolnej własnej floty. Flota w drodze nie służy za punkt desantu.',
  'hero.ability.bulwark.desc': 'Tymczasowa tarcza: +15% do obrony własnych flot w promieniu 42 od bohatera na 2 godz. Sieć dowodzenia zwiększa promień do 220 i 334.',
  'hero.ability.bulwark.name': 'Bastion',
  'hero.ability.corridor.desc': 'Korytarz do świata w zasięgu do 300: +50% do prędkości flot bohatera. Przejść może tylko armia bohatera, po jej przybyciu korytarz znika. Ulepszenia utrzymują go przez 6 godz., otwierając dla wszystkich.',
  'hero.ability.corridor.name': 'Korytarz',
  'hero.ability.decoy-signal.desc': 'Fałszuje kontakt radarowy: węzeł w zasięgu do 400 jest widziany przez wrogie radary jako zajęty (sygnatura 8) przez 4 godz. Znika, gdy wróg podejdzie blisko.',
  'hero.ability.diplomatic-landing.desc': 'Pasywna. Sojusznicze światy przyjmują bohatera jak swego: jego okręt może wystartować z planety sojusznika.',
  'hero.ability.hive-call.desc': '+15% do obrażeń flot Roju w promieniu 220 od Lewiatana na 2 godz.',
  'hero.ability.devour.desc': 'Świat bombardowany przez Lewiatana po 4 godz. staje się martwym światem. Bitwa z jego flotą lub opuszczenie orbity przerywa oblężenie.',
  'hero.ability.rally.desc': 'Okrzyk bojowy: +10% do obrażeń własnych flot w promieniu 42 od bohatera na 2 godz. Sieć dowodzenia zwiększa promień do 220 i 334.',
  'hero.ability.rally.name': 'Zbiórka',
  'hero.ability.recall.desc': 'Błyskawicznie odwołuje okręt bohatera do stolicy.',
  'hero.ability.recall.name': 'Odwołanie',
  'hero.ability.scan.desc': 'Rozprasza mgłę w promieniu 250 wokół celu w zasięgu do 400 na 3 godz. Ulepszenia dodają +5% obrażeń wrogom w strefie, a potem −5% obrażeń własnym jednostkom.',
  'hero.ability.scan.name': 'Skan',
  'hero.ability.warp-jump.desc': 'Przebicie czasoprzestrzeni: okręt bohatera z desantem natychmiast skacze do węzła w zasięgu do 350, także przez mgłę. Niedostępne podczas walki.',
