  'hero.passive.convoy-impulse.desc': 'Floty rozpoczynające przelot z węzła w promieniu 42 od bohatera pokonują ten etap o 8% szybciej.',
  'hero.passive.rally-beacon.desc': '+8% do obrażeń własnych flot w promieniu 42 od bohatera.',
  'hero.passive.asteroid-pilot.desc': '+20% do prędkości okrętu bohatera na obszarach asteroid.',
  'hero.passive.vanguard-impulse.desc': '+10% do prędkości floty bohatera.',
  'hero.tree.corridor-open.desc': 'Otwiera korytarz dla wszystkich, także dla wroga. Sojusznicy poruszają się nim z przyspieszeniem +50%.',
  'hero.tree.corridor-sustained.desc': 'Korytarz pozostaje otwarty po przejściu armii bohatera i trwa 6 godzin od momentu aktywacji.',
  'hero.tree.command-relay.desc': 'Przekaźnik przesyła rozkaz do sąsiedniego węzła: promień aur «Zbiórka» i «Bastion» rośnie z 42 do 220.',
  'hero.tree.command-grid.desc': 'Sieć obejmuje całe sąsiedztwo: promień aur «Zbiórka» i «Bastion» rośnie z 220 do 334.',
  'hero.tree.false-echo.desc': 'Odblokowuje zdolność «Fałszywy sygnał».',
  'hero.tree.fleet-uplink.desc': 'Łącze neuronalne obejmuje całe ugrupowanie: floty wylatujące z węzła w promieniu 42 pokonują trasę o 8% szybciej.',
  'hero.tree.asteroid-navigation.desc': 'Nawigacja w szczątkach: +20% do prędkości okrętu bohatera w pasie asteroid.',
  'hero.tree.neural-lace.desc': 'Implant mózg-ster: +10% do prędkości floty bohatera.',
  'hero.tree.overclocked-helm.desc': 'Przetaktowanie interfejsu odblokowuje bohaterowi zdolność «Korytarz».',
  'hero.tree.psi-evasion.desc': 'Własne i sojusznicze floty w strefie «Skanu» otrzymują o 5% mniej obrażeń.',
  'hero.tree.psi-veil.desc': 'Wyostrzone postrzeganie psioniczne: odblokowuje zdolność «Skan».',
  'hero.tree.psi-weak-points.desc': 'Radar wychwytuje luki w pancerzu wroga: floty przeciwnika w strefie «Skanu» otrzymują o 5% więcej obrażeń.',
  'hero.tree.void-attunement.desc': 'Rezonans psioniczny bohatera zagrzewa pobliskie floty: +8% do obrażeń własnych sił w promieniu 42.',
  'hero.tree.void-translocator.desc': 'Awaria korytarza wyrzuciła niegdyś okręt daleko za cel, a ten wrócił nienaruszony. Dziś wywołuje się ją celowo: odblokowuje «Skok warp».',
  'hero.unit.commander.desc': 'Główny bohater-flagowiec: dowódca transhumanista, wzmacnia flotę i otwiera korytarze.',
  'hero.unit.leviathan.desc': 'Boss zaprawionego w bojach Roju: żywy flagowiec, 900 kadłuba i 240 chityny odnawiającej się między walkami. Przybywa w ostatniej fali; śmierć jest ostateczna.',
  'hero.unit.ravager.desc': 'Niszczyciel psioniczny: anihiluje światy i rozdziera mgłę.',
  'hero.unit.scientist.desc': 'Analityk: odsłania mgłę zwiadem. Cecha wrodzona — «Laboratorium polowe»: +10% do łupów w walkach bohatera.',
  'hero.unit.vanguard.desc': 'Transhumanista manewrowy: korytarze i okrzyk bojowy dla przednich formacji.',
  'hero.unit.warden.desc': 'Obrońca psioniczny: trzyma linię za tarczą bastionu.',
