  'tech.node.ace-programs.desc': 'Program asów: elitarne załogi. +6% do obrażeń promów i prędkości flot. Zwieńczenie Dowódcy Skrzydła.',
  'tech.node.ai-stewardship.desc': 'Automatyzacja dowodzenia: zaufane SI obejmuje stery, gdy jesteś offline (śpisz). Wymaga naukowca-Nadzorcy i odblokowuje się w połowie gry (dzień 16).',
  'tech.node.combined-arms.desc': 'Walka połączonych rodzajów sił: zgranie piechoty i pancerza. +5% do obrażeń w walce lądowej.',
  'tech.node.deep-survey.desc': 'Sieci dalekich czujników: +15% do zasięgu radarów.',
  'tech.node.flight-decks.desc': 'Pokłady lotnicze: szybki cykl wylotów. +6% do prędkości flot.',
  'tech.node.fortified-infrastructure.desc': 'Doktryna umocnionych światów — twierdze pogranicza.',
  'tech.node.garrison-networks.desc': 'Sieci garnizonowe: samowystarczalne zaplecze. +5% do produkcji.',
  'tech.node.guidance-arrays.desc': 'Matryce naprowadzania: telemetria dalekiego zasięgu. +10% do zasięgu radarów.',
  'tech.node.industrial-automation.desc': 'Ulepszenie logistyki planetarnej: +10% do produkcji.',
  'tech.node.logistics-command.desc': 'Sztab logistyki: konwoje według rozkładu. +5% do produkcji i prędkości flot.',
  'tech.node.microelectronics-fabrication.desc': 'Stocznie orbitalne: +5% do produkcji.',
  'tech.node.void-shipworks.desc': 'Pomosty cumownicze i rusztowania na pancerzu twierdzy. Daje własny hangar — promy nie potrzebują już kosmodromu na planecie.',
  'tech.node.void-shielding.desc': 'Emitery pola na kadłubie twierdzy: salwa jest rozpraszana nim dotrze do pancerza. Odblokowuje obwód osłon — trzy silniejsze stopnie.',
  'tech.node.void-fortification.desc': 'Węzeł oporu poza układem: szkielet nośny i reaktor zamieniają pustkę w cenną twierdzę. Odblokowuje budowę twierdzy kosmicznej.',
  'tech.node.orbital-defense-grid.desc': 'Orbitalna sieć obronna: odblokowuje budowę orbitalnej OPL — baterii rażącej wrogą flotę na orbicie.',
  'tech.node.orbital-logistics.desc': 'Standaryzacja transportu: +12% do prędkości flot.',
  'tech.node.planetary-bastions.desc': 'Bastiony planetarne: przemysł obronny pełnego cyklu. +8% do obrażeń w walce lądowej. Zwieńczenie Marszałka.',
  'tech.node.saturation-barrage.desc': 'Salwa nasycająca: przełamanie wszelkiej obrony przeciwrakietowej. +10% do obrażeń rakiet. Zwieńczenie Artylerzysty.',
  'tech.node.siege-doctrine.desc': 'Oddziały oblężnicze dalekiego zasięgu: +8% do obrażeń w kosmosie.',
  'tech.node.signal-corps.desc': 'Wojska łączności: spójny obraz pola walki. +8% do zasięgu radarów.',
  'tech.node.strike-vectors.desc': 'Wektory uderzeniowe: precyzyjne podejścia promów. +8% do obrażeń promów.',
  'tech.node.void-armadas.desc': 'Doktryna wielkich formacji: +6% do obrażeń w kosmosie i prędkości flot. Wymaga 5 własnych sektorów.',
  'tech.node.warhead-miniaturization.desc': 'Miniaturyzacja głowic: gęstsza salwa przy tej samej masie. +6% do obrażeń rakiet.',
